select
    log2(least(greatest(cast(0.002497283380020013 as float8) * bf_first_name * bf_tf_adj_first_name * bf_surname * bf_tf_adj_surname * bf_dob * bf_city * bf_tf_adj_city * bf_email * bf_tf_adj_email, 1e-300), 1e300)) as match_weight,
    CASE WHEN bf_first_name = cast('infinity' as float8) OR bf_tf_adj_first_name = cast('infinity' as float8) OR bf_surname = cast('infinity' as float8) OR bf_tf_adj_surname = cast('infinity' as float8) OR bf_dob = cast('infinity' as float8) OR bf_city = cast('infinity' as float8) OR bf_tf_adj_city = cast('infinity' as float8) OR bf_email = cast('infinity' as float8) OR bf_tf_adj_email = cast('infinity' as float8) THEN 1.0 ELSE (least(greatest(cast(0.002497283380020013 as float8) * bf_first_name * bf_tf_adj_first_name * bf_surname * bf_tf_adj_surname * bf_dob * bf_city * bf_tf_adj_city * bf_email * bf_tf_adj_email, 1e-300), 1e300))/(1+(least(greatest(cast(0.002497283380020013 as float8) * bf_first_name * bf_tf_adj_first_name * bf_surname * bf_tf_adj_surname * bf_dob * bf_city * bf_tf_adj_city * bf_email * bf_tf_adj_email, 1e-300), 1e300))) END as match_probability,
